-- Sprint 10C additive schema: durable agent jobs, provider-call journal, checkpoints, interpreted queries, recovery
-- events. IDs are generated by the application. No destructive DDL; no baseline table is altered.
CREATE TABLE IF NOT EXISTS agent_jobs (
  id uuid PRIMARY KEY,
  access_token_hash text NOT NULL,
  request jsonb NOT NULL,
  kind text NOT NULL CHECK (kind IN ('execute','confirm','continue')),
  status text NOT NULL CHECK (status IN ('QUEUED','RUNNING','RECOVERING','COMPLETED','FAILED','CANCELLED','INTERRUPTED_UNCERTAIN','EXPIRED')),
  stage text NOT NULL DEFAULT 'queued',
  intent text,
  run_id uuid,
  parent_run_id uuid,
  base_checkpoint_id bigint,
  origin_scope text,
  attempt integer NOT NULL DEFAULT 0 CHECK (attempt >= 0),
  lease_owner uuid,
  lease_epoch integer NOT NULL DEFAULT 0,
  lease_until timestamptz,
  heartbeat_at timestamptz,
  deadline_at timestamptz NOT NULL,
  cancel_requested boolean NOT NULL DEFAULT false,
  unknown_authorized_at timestamptz,
  spend_authorized_usd numeric(10,4),
  result jsonb,
  error_code text,
  error_message text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  expires_at timestamptz
);
CREATE INDEX IF NOT EXISTS agent_jobs_recoverable_idx ON agent_jobs (status, lease_until) WHERE status IN ('QUEUED','RUNNING','RECOVERING');
CREATE INDEX IF NOT EXISTS agent_jobs_expiry_idx ON agent_jobs (expires_at) WHERE expires_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS agent_jobs_run_idx ON agent_jobs (run_id);
CREATE INDEX IF NOT EXISTS agent_jobs_origin_idx ON agent_jobs (origin_scope) WHERE origin_scope IS NOT NULL;

-- One row per logical provider operation of a job. op_key is deterministic (kind, request fingerprint, occurrence), so
-- a replay after a restart finds the same row. The row is the evidence ledger for that call.
CREATE TABLE IF NOT EXISTS agent_provider_calls (
  job_id uuid NOT NULL REFERENCES agent_jobs(id) ON DELETE CASCADE,
  op_key text NOT NULL,
  provider text NOT NULL CHECK (provider IN ('qloo','model','interpreter')),
  operation text NOT NULL,
  fingerprint text NOT NULL,
  status text NOT NULL CHECK (status IN ('RESERVED','DISPATCHING','COMPLETED','FAILED','OUTCOME_UNKNOWN','UNKNOWN_ACCEPTED')),
  attempt integer NOT NULL DEFAULT 1 CHECK (attempt > 0),
  dispatch_count integer NOT NULL DEFAULT 0 CHECK (dispatch_count >= 0),
  lease_epoch integer NOT NULL,
  correlation_id text,
  result jsonb,
  usage jsonb,
  discarded boolean NOT NULL DEFAULT false,
  error_code text,
  reserved_at timestamptz NOT NULL DEFAULT now(),
  dispatched_at timestamptz,
  completed_at timestamptz,
  PRIMARY KEY (job_id, op_key)
);
CREATE INDEX IF NOT EXISTS agent_provider_calls_status_idx ON agent_provider_calls (job_id, status);

-- Versioned snapshots of committed run state. Only the last few per run are kept (application-pruned).
CREATE TABLE IF NOT EXISTS agent_checkpoints (
  id bigserial PRIMARY KEY,
  job_id uuid NOT NULL REFERENCES agent_jobs(id) ON DELETE CASCADE,
  run_id uuid NOT NULL,
  seq integer NOT NULL CHECK (seq > 0),
  boundary text NOT NULL CHECK (boundary IN ('intake','turn','needs_input','final')),
  schema_version text NOT NULL,
  digest text NOT NULL,
  state jsonb NOT NULL,
  lease_epoch integer NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (job_id, run_id, seq)
);
CREATE INDEX IF NOT EXISTS agent_checkpoints_run_idx ON agent_checkpoints (run_id, id DESC);

-- Interpreted queries that can be confirmed later. executed_by_job makes confirmation single-use across restarts.
CREATE TABLE IF NOT EXISTS agent_queries (
  query_id uuid PRIMARY KEY,
  record jsonb NOT NULL,
  executed boolean NOT NULL DEFAULT false,
  executed_by_job uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS agent_queries_expiry_idx ON agent_queries (expires_at);

-- Minimal operational log: recovery decisions, lease changes, quarantine. Never prompts, tokens or raw provider output.
CREATE TABLE IF NOT EXISTS agent_events (
  id bigserial PRIMARY KEY,
  job_id uuid REFERENCES agent_jobs(id) ON DELETE CASCADE,
  event_type text NOT NULL,
  detail jsonb NOT NULL DEFAULT '{}',
  occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS agent_events_job_idx ON agent_events (job_id, occurred_at);
